<?php
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM therapists WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=db()->query('SELECT t.*, (SELECT COUNT(*) FROM appointments a WHERE a.therapist_id=t.id AND a.status=\'completed\') completed_count FROM therapists t ORDER BY t.full_name')->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">People & availability</div><h1>Therapists & staff</h1><p>Maintain therapist profiles and operational availability.</p></div><?php if(is_admin()):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#therapistModal"><i class="bi bi-person-plus me-1"></i>Add therapist</button><?php endif;?></div>
<div class="row g-3"><?php if(!$rows):?><div class="col-12"><div class="card empty-state"><i class="bi bi-person-badge"></i>No therapist profiles yet.</div></div><?php endif;?><?php foreach($rows as $t):?><div class="col-md-6 col-xl-4"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between align-items-start"><div class="d-flex gap-3"><div class="stat-icon" style="width:48px;height:48px;border-radius:50%;overflow:hidden"><?php if($t['profile_image']):?><img src="<?=h(app_url($t['profile_image']))?>" alt="" style="width:100%;height:100%;object-fit:cover"><?php else:?><i class="bi bi-person-fill"></i><?php endif;?></div><div><h5 class="mb-1 fw-bold"><?=h($t['full_name'])?></h5><div class="small-muted"><?=h($t['employee_code'])?> · <?=h($t['position'])?></div></div></div><?php if(is_admin()):?><a class="btn btn-sm btn-light" href="<?=h(app_page_url('therapists',['edit'=>$t['id']]))?>"><i class="bi bi-pencil"></i></a><?php endif;?></div><div class="d-flex gap-2 flex-wrap my-3"><?=status_badge($t['status'])?><?=status_badge($t['availability_status'])?></div><div class="small-muted mb-1">Specialization</div><div class="mb-3"><?=h($t['specialization']?:'Not specified')?></div><div class="d-flex justify-content-between border-top pt-3"><div><div class="small-muted">Contact</div><strong><?=h($t['phone']?:'—')?></strong></div><div class="text-end"><div class="small-muted">Completed sessions</div><strong><?=h($t['completed_count'])?></strong></div></div></div></div></div><?php endforeach;?></div>
<?php if(is_admin()):?><div class="modal fade" id="therapistModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" enctype="multipart/form-data">
<?=csrf_field()?>
<input type="hidden" name="action" value="save_therapist"><input type="hidden" name="_return" value="<?=h(app_page_url('therapists'))?>">
<div class="modal-header"><h5 class="modal-title"><?=$edit?'Edit therapist':'Add therapist'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" name="full_name" required value="<?=h($edit['full_name']??'')?>"></div><div class="col-md-6"><label class="form-label">Contact number</label><input class="form-control" name="phone" value="<?=h($edit['phone']??'')?>"></div><div class="col-md-6"><label class="form-label">Position</label><input class="form-control" name="position" value="<?=h($edit['position']??'Therapist')?>"></div><div class="col-md-6"><label class="form-label">Specialization</label><input class="form-control" name="specialization" placeholder="e.g. Hilot, Swedish massage" value="<?=h($edit['specialization']??'')?>"></div><div class="col-md-6"><label class="form-label">Hire date</label><input type="date" class="form-control" name="hire_date" value="<?=h($edit['hire_date']??'')?>"></div><div class="col-md-6"><label class="form-label">Employment status</label><select class="form-select" name="status"><option value="active" <?=selected($edit['status']??'active','active')?>>Active</option><option value="inactive" <?=selected($edit['status']??'','inactive')?>>Inactive</option></select></div><div class="col-md-6"><label class="form-label">Availability</label><select class="form-select" name="availability_status"><?php foreach(['available','busy','on_break','off_duty','inactive'] as $v):?><option value="<?=$v?>" <?=selected($edit['availability_status']??'available',$v)?>><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Address</label><input class="form-control" name="address" value="<?=h($edit['address']??'')?>"></div><div class="col-12"><label class="form-label">Profile image (JPG, PNG, WebP; max 2 MB)</label><input type="file" class="form-control" name="profile_image" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes"><?=h($edit['notes']??'')?></textarea></div></div></div><div class="modal-footer"><a href="<?=h(app_page_url('therapists'))?>" class="btn btn-light">Cancel</a><button class="btn btn-primary">Save therapist</button></form></div></div></div></div><?php if($edit):?><script>document.addEventListener('DOMContentLoaded',()=>new bootstrap.Modal(document.getElementById('therapistModal')).show());</script><?php endif;?><?php endif;?>
